def verify_goldbach(limit=1_000_000):
    # 埃氏筛，生成小于 limit 的所有素数
    is_prime = [True] * limit
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(limit ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, limit, i):
                is_prime[j] = False

    primes = [num for num, is_p in enumerate(is_prime) if is_p]
    prime_set = set(primes)

    # 对每个偶数 n 检查是否可拆成两个素数
    for n in range(4, limit, 2):
        for p in primes:
            if p > n // 2:
                break
            if n - p in prime_set:
                break
        else:
            raise AssertionError(f"反例：{n}")

    return True

if __name__ == "__main__":
    print(verify_goldbach())
```

